#!/usr/bin/env bash
# Generated by orca-setup from .orca-setup.json; change that file or the kit, not this one.
# The architect's plan gates, run in the plan worktree before the merge. Runs from an Orca
# terminal: `orca terminal create --worktree path:<worktree> --command "exec ./scripts/orca/plan-gates.sh"`.
# Every step runs even after a failure, so one run shows all problems. Prints one
# "=== <step> exit <code>" line per step and "GATES OK" or "GATES FAILED: <steps>"; the full
# output goes to .scratch/tmp/plan-gates.log.
set -uo pipefail
cd "$(dirname "$0")/../.." || exit 1

if [ "$(git rev-parse --absolute-git-dir)" = "$(git rev-parse --path-format=absolute --git-common-dir)" ]; then
  echo "plan-gates: run it in a plan worktree, not in the main checkout" >&2
  exit 1
fi

mkdir -p .scratch/tmp
log=.scratch/tmp/plan-gates.log
: > "$log"
failed=()

step() {
  local name=$1 code
  shift
  echo "=== $name" >> "$log"
  "$@" >> "$log" 2>&1
  code=$?
  echo "=== $name exit $code"
  [ "$code" -eq 0 ] || failed+=("$name")
}

install() {
  # Finder can write .DS_Store into the dependency folder while it is replaced (ENOTEMPTY); retry once.
  # An interrupted install can exit 0 with packages half written, so each attempt is verified.
  { npm_config_cache="$PWD/.npm-cache" npm ci && npm ls --depth=0; } || { npm_config_cache="$PWD/.npm-cache" npm ci && npm ls --depth=0; }
}

clean_tree() { [ -z "$(git status --porcelain)" ]; }

step install install
step test npm test
step check-commits scripts/orca/check-commits.sh main..HEAD
step clean-tree clean_tree

echo "log: $log"
if [ "${#failed[@]}" -eq 0 ]; then
  echo "GATES OK" | tee -a "$log"
else
  echo "GATES FAILED: ${failed[*]}" | tee -a "$log"
  exit 1
fi
